1	// Package store keeps Tally's data in memory. It is safe for concurrent use.
2	//
3	// Every object belongs to one organization. Methods that take an orgID only ever see that organization's objects; the few
4	// methods that find an object by ID alone (CustomerByID, InvoiceByID, EventByID) are for background jobs and the admin
5	// tool, which act on behalf of the system rather than a member.
6	package store
7	
8	import (
9		"crypto/rand"
10		"encoding/hex"
11		"errors"
12		"fmt"
13		"sort"
14		"strings"
15		"sync"
16		"time"
17	)
18	
19	// Errors. Callers check them with errors.Is; most are wrapped with a detail.
20	var (
21		ErrNotFound      = errors.New("not found")
22		ErrInvalid       = errors.New("invalid")
23		ErrConflict      = errors.New("conflict")
24		ErrEmailTaken    = fmt.Errorf("%w: email address already in use", ErrConflict)
25		ErrAlreadyMember = fmt.Errorf("%w: already a member", ErrConflict)
26		// ErrCustomerOrgMismatch is returned when an object names a customer of another organization.
27		ErrCustomerOrgMismatch = errors.New("customer belongs to another organization")
28	)
29	
30	// Store holds everything.
31	type Store struct {
32		mu  sync.Mutex
33		seq int
34	
35		orgs         map[string]Org
36		users        map[string]User
37		usersByEmail map[string]string // lower-case email -> user ID
38		members      map[memberKey]Member
39		apiKeys      map[string]APIKey
40		keysByToken  map[string]string // token -> key ID
41		invites      map[string]Invite
42	
43		customers        map[string]Customer
44		customersByEmail map[string]string // lower-case email -> customer ID
45	
46		plans     map[string]Plan
47		subs      map[string]Subscription
48		usage     []UsageRecord
49		invoices  map[string]Invoice
50		payments  map[string]Payment
51		endpoints map[string]WebhookEndpoint
52		events    map[string]Event
53		delivs    map[string]Delivery
54	}
55	
56	type memberKey struct{ org, user string }
57	
58	// New returns an empty store.
59	func New() *Store {
60		return &Store{
61			orgs: map[string]Org{}, users: map[string]User{}, usersByEmail: map[string]string{}, members: map[memberKey]Member{},
62			apiKeys: map[string]APIKey{}, keysByToken: map[string]string{}, invites: map[string]Invite{},
63			customers: map[string]Customer{}, customersByEmail: map[string]string{},
64			plans: map[string]Plan{}, subs: map[string]Subscription{}, invoices: map[string]Invoice{}, payments: map[string]Payment{},
65			endpoints: map[string]WebhookEndpoint{}, events: map[string]Event{}, delivs: map[string]Delivery{},
66		}
67	}
68	
69	// newID returns the next ID with the prefix, for example "cus_000042". The caller holds the lock.
70	func (s *Store) newID(prefix string) string {
71		s.seq++
72		return fmt.Sprintf("%s_%06d", prefix, s.seq)
73	}
74	
75	// NewToken returns prefix followed by 32 random hex characters.
76	func NewToken(prefix string) string {
77		b := make([]byte, 16)
78		if _, err := rand.Read(b); err != nil {
79			panic(err) // crypto/rand does not fail on supported platforms
80		}
81		return prefix + hex.EncodeToString(b)
82	}
83	
84	func normEmail(email string) string { return strings.ToLower(strings.TrimSpace(email)) }
85	
86	func validEmail(email string) bool {
87		at := strings.Index(email, "@")
88		return at > 0 && at < len(email)-1 && !strings.ContainsAny(email, " \t\r\n,;<>")
89	}
90	
91	func invalid(format string, args ...any) error {
92		return fmt.Errorf("%w: %s", ErrInvalid, fmt.Sprintf(format, args...))
93	}
94	
95	// ---- organizations
96	
97	// CreateOrg adds an organization.
98	func (s *Store) CreateOrg(name string, plan OrgPlan, timeZone string, taxRateBP int, now time.Time) (Org, error) {
99		o := Org{Name: strings.TrimSpace(name), Plan: plan, TimeZone: timeZone, TaxRateBP: taxRateBP, CreatedAt: now.UTC()}
100		if err := checkOrg(o); err != nil {
101			return Org{}, err
102		}
103		s.mu.Lock()
104		defer s.mu.Unlock()
105		o.ID = s.newID("org")
106		s.orgs[o.ID] = o
107		return o, nil
108	}
109	
110	func checkOrg(o Org) error {
111		if o.Name == "" {
112			return invalid("an organization needs a name")
113		}
114		if !o.Plan.Valid() {
115			return invalid("unknown plan %q", o.Plan)
116		}
117		if _, err := time.LoadLocation(o.TimeZone); err != nil || o.TimeZone == "" {
118			return invalid("unknown time zone %q", o.TimeZone)
119		}
120		if o.TaxRateBP < 0 || o.TaxRateBP > 10000 {
121			return invalid("the tax rate is 0 to 10000 basis points")
122		}
123		return nil
124	}
125	
126	// Org returns an organization.
127	func (s *Store) Org(id string) (Org, bool) {
128		s.mu.Lock()
129		defer s.mu.Unlock()
130		o, ok := s.orgs[id]
131		return o, ok
132	}
133	
134	// UpdateOrg changes an organization with f, which may refuse with an error.
135	func (s *Store) UpdateOrg(id string, f func(*Org) error) (Org, error) {
136		s.mu.Lock()
137		defer s.mu.Unlock()
138		o, ok := s.orgs[id]
139		if !ok {
140			return Org{}, ErrNotFound
141		}
142		if err := f(&o); err != nil {
143			return Org{}, err
144		}
145		o.ID = id
146		if err := checkOrg(o); err != nil {
147			return Org{}, err
148		}
149		s.orgs[id] = o
150		return o, nil
151	}
152	
153	// ---- users and members
154	
155	// CreateUser adds a user. Email addresses are unique, ignoring case.
156	func (s *Store) CreateUser(email, name string, now time.Time) (User, error) {
157		email, name = strings.TrimSpace(email), strings.TrimSpace(name)
158		if !validEmail(email) {
159			return User{}, invalid("a user needs a valid email address")
160		}
161		if name == "" {
162			return User{}, invalid("a user needs a name")
163		}
164		s.mu.Lock()
165		defer s.mu.Unlock()
166		if _, ok := s.usersByEmail[normEmail(email)]; ok {
167			return User{}, ErrEmailTaken
168		}
169		u := User{ID: s.newID("usr"), Email: email, Name: name, CreatedAt: now.UTC()}
170		s.users[u.ID] = u
171		s.usersByEmail[normEmail(email)] = u.ID
172		return u, nil
173	}
174	
175	// User returns a user.
176	func (s *Store) User(id string) (User, bool) {
177		s.mu.Lock()
178		defer s.mu.Unlock()
179		u, ok := s.users[id]
180		return u, ok
181	}
182	
183	// UserByEmail finds a user by email address, ignoring case.
184	func (s *Store) UserByEmail(email string) (User, bool) {
185		s.mu.Lock()
186		defer s.mu.Unlock()
187		id, ok := s.usersByEmail[normEmail(email)]
188		if !ok {
189			return User{}, false
190		}
191		return s.users[id], true
192	}
193	
194	// AddMember makes a user a member of an organization.
195	func (s *Store) AddMember(orgID, userID string, role Role, now time.Time) (Member, error) {
196		if !role.Valid() {
197			return Member{}, invalid("unknown role %q", role)
198		}
199		s.mu.Lock()
200		defer s.mu.Unlock()
201		return s.addMember(orgID, userID, role, now)
202	}
203	
204	func (s *Store) addMember(orgID, userID string, role Role, now time.Time) (Member, error) {
205		if _, ok := s.orgs[orgID]; !ok {
206			return Member{}, ErrNotFound
207		}
208		if _, ok := s.users[userID]; !ok {
209			return Member{}, ErrNotFound
210		}
211		k := memberKey{orgID, userID}
212		if _, ok := s.members[k]; ok {
213			return Member{}, ErrAlreadyMember
214		}
215		m := Member{OrgID: orgID, UserID: userID, Role: role, CreatedAt: now.UTC()}
216		s.members[k] = m
217		return m, nil
218	}
219	
220	// Member returns a user's membership of an organization.
221	func (s *Store) Member(orgID, userID string) (Member, bool) {
222		s.mu.Lock()
223		defer s.mu.Unlock()
224		m, ok := s.members[memberKey{orgID, userID}]
225		return m, ok
226	}
227	
228	// Members returns an organization's members, oldest first.
229	func (s *Store) Members(orgID string) []Member {
230		s.mu.Lock()
231		defer s.mu.Unlock()
232		out := []Member{}
233		for _, m := range s.members {
234			if m.OrgID == orgID {
235				out = append(out, m)
236			}
237		}
238		sort.Slice(out, func(i, j int) bool {
239			if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
240				return out[i].CreatedAt.Before(out[j].CreatedAt)
241			}
242			return out[i].UserID < out[j].UserID
243		})
244		return out
245	}
246	
247	// SetMemberRole changes a member's role.
248	func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
249		if !role.Valid() {
250			return Member{}, invalid("unknown role %q", role)
251		}
252		s.mu.Lock()
253		defer s.mu.Unlock()
254		k := memberKey{orgID, userID}
255		m, ok := s.members[k]
256		if !ok {
257			return Member{}, ErrNotFound
258		}
259		m.Role = role
260		s.members[k] = m
261		return m, nil
262	}
263	
264	// RemoveMember removes a user from an organization. Their API keys for it stop working, as they are no longer a member.
265	func (s *Store) RemoveMember(orgID, userID string) error {
266		s.mu.Lock()
267		defer s.mu.Unlock()
268		k := memberKey{orgID, userID}
269		if _, ok := s.members[k]; !ok {
270			return ErrNotFound
271		}
272		delete(s.members, k)
273		return nil
274	}
