// NumberInvoices gives each invoice that has no number the next number of its organization, in creation order (created_at,
// then ID), and sets each organization's next number after them. Invoices that have a number keep it. It is for states
// from snapshots that predate invoice numbers.
func NumberInvoices(st *State) {
	if st.InvoiceNext == nil {
		st.InvoiceNext = map[string]int{}
	}
	sort.Slice(st.Invoices, func(i, j int) bool {
		a, b := st.Invoices[i], st.Invoices[j]
		if !a.CreatedAt.Equal(b.CreatedAt) {
			return a.CreatedAt.Before(b.CreatedAt)
		}
		return a.ID < b.ID
	})
	for i := range st.Invoices {
		inv := &st.Invoices[i]
		if inv.Number != "" {
			continue
		}
		n := st.InvoiceNext[inv.OrgID]
		if n == 0 {
			n = 1
		}
		inv.Number = invoiceNumber(n)
		st.InvoiceNext[inv.OrgID] = n + 1
	}
}

