// Version is the version Save writes. Version 3 numbers invoices and keeps each organization's next number.
const Version = 3

// ErrUnsupportedVersion is returned for a file of a version Load cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

type fileV2 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

type fileV3 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Save writes everything in st to path. The file is replaced atomically: after a crash, path holds either the previous
// snapshot or this one in full.
func Save(st *store.Store, path string, now time.Time) error {
	b, err := json.MarshalIndent(fileV3{Version: Version, SavedAt: now.UTC(), State: st.Export()}, "", "  ")
	if err != nil {
		return err
	}
	return writeFileAtomic(path, append(b, '\n'))
}

// writeFileAtomic writes data to a temporary file in the folder of path, then renames it over path. The temporary file is
// removed if anything fails.
func writeFileAtomic(path string, data []byte) (err error) {
	dir := filepath.Dir(path)
	tmp, err := os.CreateTemp(dir, filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			_ = tmp.Close()
			_ = os.Remove(tmp.Name())
		}
	}()
	if _, err = tmp.Write(data); err != nil {
		return err
	}
	if err = tmp.Sync(); err != nil {
		return err
	}
	if err = tmp.Close(); err != nil {
		return err
	}
	if err = os.Rename(tmp.Name(), path); err != nil {
		return err
	}
	return syncDir(dir)
}

// syncDir flushes a folder, so a rename in it survives a crash.
func syncDir(dir string) error {
	d, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer d.Close()
	return d.Sync()
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	st, _, err := decode(path, b)
	if err != nil {
		return nil, err
	}
	return store.FromState(st)
}

// Upgrade rewrites a snapshot of an older version as Version. First it copies the original, byte for byte, to
// "<path>.v<version>.bak". A snapshot already at Version is left alone, and one of a newer version fails with
// ErrUnsupportedVersion without changes.
func Upgrade(path string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	st, ver, err := decode(path, b)
	if err != nil {
		return err
	}
	if ver == Version {
		return nil
	}
	s, err := store.FromState(st)
	if err != nil {
		return err
	}
	if err := writeNew(fmt.Sprintf("%s.v%d.bak", path, ver), b); err != nil {
		return err
	}
	return Save(s, path, time.Now())
}

// writeNew creates a file with data and syncs it. It fails if the file already exists, so a backup is never overwritten.
func writeNew(path string, data []byte) error {
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return err
	}
	_, err = f.Write(data)
	if err == nil {
		err = f.Sync()
	}
	if cerr := f.Close(); err == nil {
		err = cerr
	}
	if err != nil {
		_ = os.Remove(path)
	}
	return err
}

// decode reads the state in the contents b of the snapshot at path, and returns the snapshot's version. Versions 1 and 2
// have no invoice numbers, so their invoices are numbered here.
func decode(path string, b []byte) (store.State, int, error) {
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return store.State{}, 0, fmt.Errorf("snapshot %s: %w", path, err)
	}
	var st store.State
	switch head.Version {
	case 1:
		var err error
		if st, err = migrateV1(b); err != nil {
			return store.State{}, 0, fmt.Errorf("snapshot %s: version 1: %w", path, err)
		}
		store.NumberInvoices(&st)
	case 2:
		var f fileV2
		if err := json.Unmarshal(b, &f); err != nil {
			return store.State{}, 0, fmt.Errorf("snapshot %s: %w", path, err)
		}
		st = f.State
		store.NumberInvoices(&st)
	case 3:
		var f fileV3
		if err := json.Unmarshal(b, &f); err != nil {
			return store.State{}, 0, fmt.Errorf("snapshot %s: %w", path, err)
