// invoiceFor creates an invoice for a customer of an organization at now.
func invoiceFor(t *testing.T, st *store.Store, orgID, customerID string, now time.Time) store.Invoice {
	t.Helper()
	inv, err := st.CreateInvoice(store.Invoice{OrgID: orgID, CustomerID: customerID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}, now)
	if err != nil {
		t.Fatal(err)
	}
	return inv
}

// writeV2 writes st as a version 2 snapshot at path, the way Tally 2 wrote it: without invoice numbers. It returns the bytes.
func writeV2(t *testing.T, path string, st *store.Store, now time.Time) []byte {
	t.Helper()
	state := st.Export()
	state.InvoiceNext = nil
	for i := range state.Invoices {
		state.Invoices[i].Number = ""
	}
	b, err := json.MarshalIndent(fileV2{Version: 2, SavedAt: now, State: state}, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, b, 0o600); err != nil {
		t.Fatal(err)
	}
	return b
}

// versionOf returns the version the snapshot at path declares.
func versionOf(t *testing.T, path string) int {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		t.Fatal(err)
	}
	return head.Version
}

