// invoiceFor creates an invoice for a customer of an organization at now.
func invoiceFor(t *testing.T, st *store.Store, orgID, customerID string, now time.Time) store.Invoice {
	t.Helper()
	inv, err := st.CreateInvoice(store.Invoice{OrgID: orgID, CustomerID: customerID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}, now)
	if err != nil {
		t.Fatal(err)
	}
	return inv
}

// writeV2 writes st as a version 2 snapshot at path, the way Tally 2 wrote it: without invoice numbers. It returns the bytes.
func writeV2(t *testing.T, path string, st *store.Store, now time.Time) []byte {
	t.Helper()
	state := st.Export()
	state.InvoiceNext = nil
	for i := range state.Invoices {
		state.Invoices[i].Number = ""
	}
	b, err := json.MarshalIndent(fileV2{Version: 2, SavedAt: now, State: state}, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, b, 0o600); err != nil {
		t.Fatal(err)
	}
	return b
}

// versionOf returns the version the snapshot at path declares.
func versionOf(t *testing.T, path string) int {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		t.Fatal(err)
	}
	return head.Version
}

func TestInvoiceNumbersArePerOrganization(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	a, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, now)
	b, _ := st.CreateOrg("B", store.OrgTeam, "UTC", 0, now)
	ca, _ := st.CreateCustomer(a.ID, "Ann", "ann@example.com", now)
	cb, _ := st.CreateCustomer(b.ID, "Bob", "bob@example.com", now)
	var got []string
	for _, inv := range []store.Invoice{
		invoiceFor(t, st, a.ID, ca.ID, now),
		invoiceFor(t, st, a.ID, ca.ID, now),
		invoiceFor(t, st, b.ID, cb.ID, now),
		invoiceFor(t, st, a.ID, ca.ID, now),
	} {
		got = append(got, inv.Number)
	}
	if want := []string{"INV-000001", "INV-000002", "INV-000001", "INV-000003"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("numbers = %v, want %v", got, want)
	}

	path := filepath.Join(t.TempDir(), "tally.json")
	if err := Save(st, path, now); err != nil {
		t.Fatal(err)
	}
	loaded, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if inv := invoiceFor(t, loaded, a.ID, ca.ID, now); inv.Number != "INV-000004" {
		t.Fatalf("next number of A = %s, want INV-000004", inv.Number)
	}
	if inv := invoiceFor(t, loaded, b.ID, cb.ID, now); inv.Number != "INV-000002" {
		t.Fatalf("next number of B = %s, want INV-000002", inv.Number)
	}
}

func TestLoadVersion2NumbersInvoicesInCreationOrder(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	o, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, now)
	c, _ := st.CreateCustomer(o.ID, "Ann", "ann@example.com", now)
	// The IDs follow the order of creation here, but the invoices carry other times.
	late := invoiceFor(t, st, o.ID, c.ID, now.Add(2*time.Hour))
	early := invoiceFor(t, st, o.ID, c.ID, now)
	middle := invoiceFor(t, st, o.ID, c.ID, now.Add(time.Hour))

	path := filepath.Join(t.TempDir(), "tally.json")
	writeV2(t, path, st, now)
	loaded, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	for id, want := range map[string]string{early.ID: "INV-000001", middle.ID: "INV-000002", late.ID: "INV-000003"} {
		inv, ok := loaded.Invoice(o.ID, id)
		if !ok || inv.Number != want {
			t.Fatalf("invoice %s has number %q, want %s", id, inv.Number, want)
		}
	}
	if inv := invoiceFor(t, loaded, o.ID, c.ID, now); inv.Number != "INV-000004" {
		t.Fatalf("the next number is %s, want INV-000004", inv.Number)
	}
}

